-- FlightSim modular runtime v5.0
local Players=game:GetService("Players"); local RunService=game:GetService("RunService"); local ReplicatedStorage=game:GetService("ReplicatedStorage")
local root=script.Parent; local systemsFolder=root:WaitForChild("FlightSimSystems"); local shared=ReplicatedStorage:WaitForChild("FlightSim"); local remotes=shared:WaitForChild("Remotes")
local Config=require(systemsFolder:WaitForChild("Config")); local State=require(systemsFolder:WaitForChild("State")); local FailureSchema=require(systemsFolder:WaitForChild("FailureSchema")); local Electrical=require(systemsFolder:WaitForChild("Electrical")); local APU=require(systemsFolder:WaitForChild("APU")); local Engine=require(systemsFolder:WaitForChild("Engine")); local Core=require(systemsFolder:WaitForChild("Core")); local Hydraulic=require(systemsFolder:WaitForChild("Hydraulic")); local Fuel=require(systemsFolder:WaitForChild("Fuel")); local FireProtection=require(systemsFolder:WaitForChild("FireProtection")); local Annunciation=require(systemsFolder:WaitForChild("Annunciation")); local FlightControls=require(systemsFolder:WaitForChild("FlightControls")); local LandingGear=require(systemsFolder:WaitForChild("LandingGear")); local Brakes=require(systemsFolder:WaitForChild("Brakes")); local Avionics=require(systemsFolder:WaitForChild("Avionics")); local Navigation=require(systemsFolder:WaitForChild("Navigation")); local NAVReceiver=require(systemsFolder:WaitForChild("NAVReceiver")); local Autopilot=require(systemsFolder:WaitForChild("Autopilot")); local AutoThrottle=require(systemsFolder:WaitForChild("AutoThrottle")); local VNAV=require(systemsFolder:WaitForChild("VNAV")); local FMC=require(systemsFolder:WaitForChild("FMC")); local MCP=require(systemsFolder:WaitForChild("MCP.v02")); local Approach=require(systemsFolder:WaitForChild("Approach")); local VOR=require(systemsFolder:WaitForChild("VOR")); local LandingModel=require(systemsFolder:WaitForChild("LandingModel")); local LandingDynamics=require(systemsFolder:WaitForChild("LandingDynamics")); local Physics=require(systemsFolder:WaitForChild("Physics")); local Trim=require(systemsFolder:WaitForChild("Trim")); local Flaps=require(systemsFolder:WaitForChild("Flaps")); local Radio=require(systemsFolder:WaitForChild("Radio")); local Transponder=require(systemsFolder:WaitForChild("Transponder")); local GroundSteering=require(systemsFolder:WaitForChild("GroundSteering")); local Failures=require(systemsFolder:WaitForChild("Failures")); local ATC=require(systemsFolder:WaitForChild("ATC")); local ATCTraffic=require(systemsFolder:WaitForChild("ATCTraffic")); local ATCSequencer=require(systemsFolder:WaitForChild("ATCSequencer")); local ATCRunway=require(systemsFolder:WaitForChild("ATCRunway")); local ATCSeparation=require(systemsFolder:WaitForChild("ATCSeparation")); local ATCDecision=require(systemsFolder:WaitForChild("ATCDecision")); local TCAS=require(systemsFolder:WaitForChild("TCAS.v02")); local TrafficDisplay=require(systemsFolder:WaitForChild("TrafficDisplay")); local Environment=require(systemsFolder:WaitForChild("Environment")); local WeatherPhysics=require(systemsFolder:WaitForChild("WeatherPhysics")); local WeatherRadar=require(systemsFolder:WaitForChild("WeatherRadar")); local Pressurization=require(systemsFolder:WaitForChild("Pressurization")); local BleedAir=require(systemsFolder:WaitForChild("BleedAir")); local AntiIce=require(systemsFolder:WaitForChild("AntiIce")); local AircraftRegistry=require(systemsFolder:WaitForChild("AircraftRegistry")); local CommandRouter=require(systemsFolder:WaitForChild("CommandRouter")); local StateIntegrity=require(systemsFolder:WaitForChild("StateIntegrity")); local SimulationClock=require(systemsFolder:WaitForChild("SimulationClock")); local AircraftModelBinder=require(systemsFolder:WaitForChild("AircraftModelBinder"))
local registry=AircraftRegistry.new(); local simulations={}; local integrity=StateIntegrity.new(); local modelBinder=AircraftModelBinder.new(); local traffic=ATCTraffic.new(); local sequencer=ATCSequencer.new(traffic); local separation=ATCSeparation.new(registry,Config); local decisions=ATCDecision.new(separation); local tcas=TCAS.new(registry); local function get(id,key) local s=simulations[id]; return s and s[key] end
local router=CommandRouter.new(registry,function(id)return get(id,"fmc") end,function(id)return get(id,"radio") end,function(id)return get(id,"transponder") end,function(id)return get(id,"mcp") end,function(id)return get(id,"approach") end,function(id)return get(id,"autothrottle") end,function(id)return get(id,"atc") end,function(id)return get(id,"atcRunway") end,function(id)return get(id,"pressurization") end,function(id)return get(id,"antiIce") end)
local function createAircraftForPlayer(player)
 local id="P_"..tostring(player.UserId); if registry:Get(id) then return end; local state=State.new(); FailureSchema.Apply(state); registry:Register(id,state,player); local atc=ATC.new(state); local callsign="FS"..tostring(player.UserId%10000); atc:SetCallsign(callsign); local atcRunway=ATCRunway.new(state,traffic,id,callsign,sequencer)
 simulations[id]={state=state,apu=APU.new(state),electrical=Electrical.new(state),engine=Engine.new(state),failures=Failures.new(state),core=Core.new(state),hydraulic=Hydraulic.new(state,Config),fuel=Fuel.new(state),fireProtection=FireProtection.new(state),bleedAir=BleedAir.new(state),pressurization=Pressurization.new(state),antiIce=AntiIce.new(state),annunciation=Annunciation.new(state),flightControls=FlightControls.new(state),landingGear=LandingGear.new(state),brakes=Brakes.new(state),avionics=Avionics.new(state),navigation=Navigation.new(state),navReceiver=NAVReceiver.new(state),autopilot=Autopilot.new(state),autothrottle=AutoThrottle.new(state),vnav=VNAV.new(state),fmc=FMC.new(state),mcp=MCP.new(state),approach=Approach.new(state),vor=VOR.new(state),landing=LandingModel.new(state),landingDynamics=LandingDynamics.new(state),flaps=Flaps.new(state),radio=Radio.new(state),transponder=Transponder.new(state),trim=Trim.new(state),groundSteering=GroundSteering.new(state),physics=Physics.new(state),atc=atc,atcRunway=atcRunway,environment=Environment.new(state),weatherPhysics=WeatherPhysics.new(state),weatherRadar=WeatherRadar.new(state),trafficDisplay=TrafficDisplay.new(state)}
 modelBinder:Bind(id,state)
end
local function removeAircraftForPlayer(player) local id="P_"..tostring(player.UserId); local s=simulations[id]; if s and s.atcRunway then s.atcRunway:Release() end; modelBinder:Unbind(id); registry:Unregister(id); simulations[id]=nil end
Players.PlayerAdded:Connect(createAircraftForPlayer); Players.PlayerRemoving:Connect(removeAircraftForPlayer); for _,p in Players:GetPlayers() do createAircraftForPlayer(p) end
local commandRemote=remotes:FindFirstChild("AircraftCommand"); if commandRemote then commandRemote.OnServerEvent:Connect(function(player,command,a,b) local id=registry:GetForPlayer(player); if not id then return end; local ok,reason=router:Handle(player,id,command,a,b); if not ok then warn("[FlightSim] rejected command",player.Name,reason) end end) end
local fixedStep=1/(tonumber(Config.SimulationRate) or 60); local clock=SimulationClock.new(fixedStep,16); local telemetryAccumulator=0
local function updateTrafficSystems() separation:Step(); decisions:Step(); registry:ForEach(function(id,state) local x=state:Get(); local d=decisions:Get(id); if d then x.ATCDecision.Instruction=d.Instruction; x.ATCDecision.ConflictWith=d.ConflictWith; x.ATCDecision.DistanceM=d.DistanceM; x.ATCDecision.VerticalSeparationFt=d.VerticalSeparationFt else x.ATCDecision.Instruction="NONE"; x.ATCDecision.ConflictWith=nil; x.ATCDecision.DistanceM=nil; x.ATCDecision.VerticalSeparationFt=nil end end); registry:ForEach(function(id) tcas:Step(id); local sim=simulations[id]; if sim and sim.trafficDisplay then sim.trafficDisplay:Step() end end) end
local function simulationStep(dt) registry:ForEach(function(id) local s=simulations[id]; if not s then return end
 s.failures:Step(dt); s.apu:Step(dt); s.fuel:Step(dt); s.electrical:Step(dt); s.engine:Step(dt); s.fireProtection:Step(dt); s.core:Step(dt); s.avionics:Step(dt); s.radio:Step(dt); s.environment:Step(dt); s.weatherPhysics:Step(dt); s.weatherRadar:Step(dt); s.bleedAir:Step(dt); s.pressurization:Step(dt); s.antiIce:Step(dt); s.atc:Step(dt); s.atcRunway:Step(dt); s.mcp:Step(dt); s.approach:Step(dt); s.vor:Step(dt); s.navReceiver:Step(dt); s.navigation:Step(dt); s.fmc:Step(dt); s.vnav:Step(dt); s.autopilot:Step(dt); s.autothrottle:Step(dt); s.trim:Step(dt); s.flaps:Step(dt); s.flightControls:Step(dt); s.landingGear:Step(dt); s.brakes:Step(dt); s.hydraulic:Step(dt); s.groundSteering:Step(dt); s.transponder:Step(dt); s.physics:Step(dt); s.landing:Step(dt); s.landingDynamics:Step(dt); s.annunciation:Step(dt)
 local ok,errors=integrity:Check(s.state); if not ok then for _,e in ipairs(errors) do warn("[FlightSim][StateIntegrity]",id,e.Code,e.Message) end end
 end); modelBinder:Refresh(); modelBinder:Step(); modelBinder:StepControls(); updateTrafficSystems() end
RunService.Heartbeat:Connect(function(frameDt) local steps,step,dropped,normalizedDt=clock:Advance(frameDt); for _=1,steps do simulationStep(step) end; if dropped>0 then warn("[FlightSim] simulation time dropped after frame stall",dropped) end; telemetryAccumulator+=normalizedDt; if telemetryAccumulator>=1/(tonumber(Config.TelemetryRate) or 20) then telemetryAccumulator=0; local t=remotes:FindFirstChild("Telemetry"); if t then registry:ForEach(function(_,state,owner) if owner then t:FireClient(owner,state:Get()) end end) end end end)
print("[FlightSim] Modular runtime online",Config.Aircraft or "Unknown aircraft")